--
-- Table structure for table `merchant`
--

DROP TABLE IF EXISTS `merchant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '店铺名称',
  `phone` varchar(20) NOT NULL COMMENT '登录手机号',
  `password` varchar(100) NOT NULL COMMENT 'BCrypt 密码',
  `category` varchar(50) DEFAULT NULL COMMENT '菜系',
  `area` varchar(50) DEFAULT NULL COMMENT '所属地区',
  `address` varchar(255) DEFAULT NULL COMMENT '详细地址',
  `intro` varchar(1000) DEFAULT NULL COMMENT '店铺简介',
  `cover_image` varchar(255) DEFAULT NULL COMMENT '店铺封面',
  `album` varchar(2000) DEFAULT NULL COMMENT '店铺相册，逗号分隔',
  `business_hours` varchar(100) DEFAULT NULL COMMENT '营业时间',
  `avg_price` decimal(10,2) DEFAULT '0.00' COMMENT '人均消费',
  `score` decimal(3,1) DEFAULT '5.0' COMMENT '综合评分（由评价聚合）',
  `score_count` int DEFAULT '0' COMMENT '评分人数',
  `favorite_count` int DEFAULT '0' COMMENT '收藏量',
  `review_count` int DEFAULT '0' COMMENT '评价数量',
  `view_count` int DEFAULT '0' COMMENT '浏览量（热度）',
  `status` tinyint DEFAULT '1' COMMENT '1 正常营业 0 停业整顿',
  `audit_status` tinyint DEFAULT '0' COMMENT '0 待审核 1 审核通过 2 已驳回',
  `audit_remark` varchar(255) DEFAULT NULL COMMENT '审核意见',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_merchant_phone` (`phone`),
  KEY `idx_merchant_category` (`category`),
  KEY `idx_merchant_area` (`area`),
  KEY `idx_merchant_audit` (`audit_status`)
) ENGINE=InnoDB AUTO_INCREMENT=221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商家表';
/*!40101 SET character_set_client = @saved_cs_client */;

