INSERT INTO `message` VALUES (1,1,1,1,'新店开业：甜蜜烘焙坊','徐汇区新开了一家手工烘焙店，开业期间全场 8 折，快去看看吧！',9,0,'2026-10-24 13:14:06'),(2,1,1,3,'优惠券开抢：满100减30','你收藏的川味小厨上线了满 100 减 30 优惠券，数量有限，先到先得。',1,0,'2026-10-24 13:14:06'),(3,1,1,2,'商家上新：招牌水煮鱼','川味小厨上架了新菜品「招牌水煮鱼」，欢迎品尝。',1,1,'2026-10-24 13:14:06'),(4,1,2,5,'商家入驻审核结果','店铺「川味小厨」已通过平台审核，可以开始营业了。',1,0,'2026-10-24 13:14:06'),(5,2,1,4,'欢迎加入美食推荐','完善口味偏好可以获得更精准的推荐哦。',NULL,1,'2026-10-24 13:14:06'),(6,6,1,4,'欢迎加入美食推荐','完善口味偏好后，系统会为你推送更精准的美食商家。',NULL,0,'2026-10-24 14:17:11'),(7,6,1,3,'优惠券开抢：异步链路测试券','你收藏的「川味小厨」上线了「异步链路测试券」，数量有限，先到先得。',4009,0,'2026-10-24 15:04:01'),(8,6,1,3,'优惠券开抢：并发压测券-5张','你收藏的「川味小厨」上线了「并发压测券-5张」，数量有限，先到先得。',4010,0,'2026-10-24 15:04:04'),(9,6,1,3,'优惠券开抢：预热验证券','你收藏的「川味小厨」上线了「预热验证券」，数量有限，先到先得。',4011,0,'2026-10-24 15:05:14'),(10,6,1,3,'优惠券开抢：预热验证券','你收藏的「川味小厨」上线了「预热验证券」，数量有限，先到先得。',4012,0,'2026-10-24 15:05:24'),(11,6,1,3,'优惠券开抢：预热验证券B','你收藏的「川味小厨」上线了「预热验证券B」，数量有限，先到先得。',4013,0,'2026-10-24 15:05:38'),(12,6,1,3,'优惠券开抢：异步链路测试券','你收藏的「川味小厨」上线了「异步链路测试券」，数量有限，先到先得。',4014,0,'2026-10-24 15:08:09'),(13,6,1,3,'优惠券开抢：并发压测券-5张','你收藏的「川味小厨」上线了「并发压测券-5张」，数量有限，先到先得。',4015,0,'2026-10-24 15:08:10'),(14,6,1,3,'优惠券开抢：商家发券演示券','你收藏的「川味小厨」上线了「商家发券演示券」，数量有限，先到先得。',4016,0,'2026-10-24 15:53:48'),(15,6,1,3,'优惠券开抢：满200减59','你收藏的「川味小厨」上线了「满200减59」，数量有限，先到先得。',4017,0,'2026-10-24 18:22:51'),(16,6,1,3,'优惠券开抢：JMeter压测券-5张','你收藏的「川味小厨」上线了「JMeter压测券-5张」，数量有限，先到先得。',4018,0,'2026-10-27 15:42:37'),(17,6,1,3,'优惠券开抢：QPS压测券-5000张','你收藏的「川味小厨」上线了「QPS压测券-5000张」，数量有限，先到先得。',4019,0,'2026-10-27 15:58:05'),(18,6,1,3,'优惠券开抢：QPS压测券-带锁','你收藏的「川味小厨」上线了「QPS压测券-带锁」，数量有限，先到先得。',4020,0,'2026-10-27 15:59:47'),(19,6,1,3,'优惠券开抢：QPS终测券-5000张','你收藏的「川味小厨」上线了「QPS终测券-5000张」，数量有限，先到先得。',4021,0,'2026-10-27 16:01:32'),(20,6,1,3,'优惠券开抢：QPS稳态券-5000张','你收藏的「川味小厨」上线了「QPS稳态券-5000张」，数量有限，先到先得。',4022,0,'2026-10-27 16:02:23');
