INSERT INTO `note` VALUES (1,1,1,'成都春熙路必吃川菜｜川味小厨探店','周末和朋友去打卡，水煮鱼麻辣鲜香，鱼片很嫩，强烈推荐！人均 70 左右，性价比很高。',NULL,NULL,137,2,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0),(2,2,2,'杭州文三路隐藏的杭帮菜馆','东坡肉真的入口即化，环境古色古香，适合家庭聚餐。',NULL,NULL,98,2,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0),(3,3,3,'北京南锣鼓巷铜锅涮肉攻略','手切鲜羊肉必点，麻酱小料是灵魂，建议提前排队。',NULL,NULL,211,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0),(4,2,4,'广州早茶｜虾饺皇天花板','虾饺皮薄到透光，一口一个，配上普洱刚刚好。',NULL,NULL,74,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0),(5,3,6,'上海静安深夜食堂｜日式居酒屋','三文鱼厚切八片，鸡皮串外酥里嫩，营业到凌晨两点。',NULL,NULL,156,40,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0),(6,1,5,'待审核笔记：湘辣坊试吃','这条笔记等待平台审核。',NULL,NULL,0,0,0,'2026-10-24 13:14:06','2026-10-24 13:14:06',0),(3001,1,101,'藏在科华北路的川菜馆，毛血旺太顶了','周末去打卡，毛血旺料很足，鸭血嫩，午餐肉厚切，配米饭能吃两碗。',NULL,NULL,30,2,1,'2026-10-23 14:35:37','2026-10-23 14:35:37',0),(3002,2,102,'广州早茶攻略｜一盅两件慢慢叹','虾饺、烧卖、凤爪都点了，茶水可以续，人均不到 100。',NULL,NULL,43,1,1,'2026-10-22 14:35:37','2026-10-22 14:35:37',0),(3003,3,103,'北京护国寺街的炸酱面','面条筋道，酱香浓郁，配一碟腊八蒜刚刚好。',NULL,NULL,56,12,1,'2026-10-21 14:35:37','2026-10-21 14:35:37',0),(3004,4,104,'苏州平江路的苏帮菜','松鼠桂鱼外酥里嫩，响油鳝糊香气扑鼻，环境很出片。',NULL,NULL,69,15,1,'2026-10-20 14:35:37','2026-10-20 14:35:37',0),(3005,1,105,'长沙五一大道夜宵地图','剁椒鱼头够辣够鲜，擂辣椒皮蛋是隐藏吃法。',NULL,NULL,82,18,1,'2026-10-19 14:35:37','2026-10-19 14:35:37',0),(3006,2,106,'东北饺子馆｜手工现包才有的味道','猪肉白菜馅汁水足，锅包肉酸甜酥脆。',NULL,NULL,95,21,1,'2026-10-18 14:35:37','2026-10-18 14:35:37',0),(3007,3,107,'西安南门里的羊肉泡馍','自己掰馍才有灵魂，汤头浓白，配糖蒜解腻。',NULL,NULL,108,24,1,'2026-10-17 14:35:37','2026-10-17 14:35:37',0),(3008,4,108,'昆明翠湖边的过桥米线','汤底滚烫，配菜新鲜，菌子季一定要加菌子。',NULL,NULL,121,27,1,'2026-10-16 14:35:37','2026-10-16 14:35:37',0),(3009,1,109,'上海仙霞路的日料小店','三文鱼厚切，天妇罗不油腻，午市套餐很划算。',NULL,NULL,134,30,1,'2026-10-15 14:35:37','2026-10-15 14:35:37',0),(3010,2,110,'中关村这家韩式烤肉值得排队','五花肉烤到微焦，配生菜和蒜片，部队锅也很足。',NULL,NULL,147,33,1,'2026-10-14 14:35:37','2026-10-14 14:35:37',0),(3011,3,111,'珠江新城的泰餐｜冬阴功太上头','酸辣开胃，咖喱蟹拌饭一绝，芒果糯米饭收尾。',NULL,NULL,160,36,1,'2026-10-13 14:35:37','2026-10-13 14:35:37',0),(3012,4,112,'南京东路的意面与牛排','手工意面有嚼劲，牛排火候刚好，适合约会。',NULL,NULL,173,39,1,'2026-10-12 14:35:37','2026-10-12 14:35:37',0),(6001,301,201,'宽窄巷子旁的蹄花汤，冬天必喝','老妈蹄花软糯脱骨，汤头奶白，配一碟蘸水很舒服。',NULL,NULL,20,3,1,'2026-10-26 02:23:14','2026-10-26 02:23:14',0),(6002,302,202,'顺德鱼生到底怎么吃','鱼生配十几种小料，捞起捞起，风生水起。',NULL,NULL,27,4,1,'2026-10-25 02:23:14','2026-10-25 02:23:14',0),(6003,303,203,'南锣鼓巷铜锅涮肉','手切羊肉立盘不倒，麻酱小料是灵魂。',NULL,NULL,34,5,1,'2026-10-24 02:23:14','2026-10-24 02:23:14',0),(6004,304,204,'苏州观前街的一碗焖肉面','焖肉入口即化，汤头清亮，早餐首选。',NULL,NULL,41,6,1,'2026-10-23 02:23:14','2026-10-23 02:23:14',0),(6005,305,205,'长沙麓山南路的小炒黄牛肉','锅气十足，牛肉嫩，配米饭能吃两碗。',NULL,NULL,48,7,1,'2026-10-22 02:23:14','2026-10-22 02:23:14',0),(6006,306,206,'大雁塔旁的 biangbiang 面','面宽如裤带，油泼辣子一浇，香。',NULL,NULL,55,8,1,'2026-10-21 02:23:14','2026-10-21 02:23:14',0),(6007,307,207,'昆明野生菌火锅','菌子拼盘很新鲜，汤底鲜到掉眉毛。',NULL,NULL,62,9,1,'2026-10-20 02:23:14','2026-10-20 02:23:14',0),(6008,308,208,'南京西路的板前寿司','食材新鲜，师傅手法利落，午市套餐划算。',NULL,NULL,69,10,1,'2026-10-19 02:23:14','2026-10-19 02:23:14',0),(6009,301,209,'望京这家韩式炸鸡','外皮酥脆，甜辣酱很上头。',NULL,NULL,76,11,1,'2026-10-18 02:23:14','2026-10-18 02:23:14',0),(6010,302,210,'中山路的海鲜粥','砂锅现煮，虾蟹给得实在，夜宵好去处。',NULL,NULL,83,12,1,'2026-10-17 02:23:14','2026-10-17 02:23:14',0);
