DROP TABLE IF EXISTS `review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `merchant_id` bigint NOT NULL,
  `dish_id` bigint DEFAULT NULL,
  `score` int DEFAULT '5' COMMENT '1-5 星',
  `content` varchar(1000) DEFAULT NULL,
  `images` varchar(2000) DEFAULT NULL COMMENT '图片地址，逗号分隔',
  `status` tinyint DEFAULT '0' COMMENT '0 待审核 1 已通过 2 违规下架',
  `like_count` int DEFAULT '0',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_review_user` (`user_id`),
  KEY `idx_review_merchant` (`merchant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5041 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评价表';
/*!40101 SET character_set_client = @saved_cs_client */;

