INSERT INTO `review` VALUES (1,1,1,1,5,'水煮鱼真的绝了，麻辣过瘾，分量也足！',NULL,1,2,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(2,2,1,3,5,'麻婆豆腐很下饭，服务员态度也好。',NULL,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(3,3,1,2,4,'夫妻肺片味道不错，就是稍微有点咸。',NULL,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(4,2,2,5,5,'东坡肉入口即化，环境安静适合约会。',NULL,1,9,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(5,4,2,6,4,'龙井虾仁很鲜，价格略贵。',NULL,1,3,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(6,3,3,8,5,'铜锅涮肉太正宗了，羊肉没有一点膻味。',NULL,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(7,4,3,10,4,'上脑不错，麻酱小料很香。',NULL,1,5,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(8,2,4,11,5,'虾饺皮薄馅大，早茶首选。',NULL,1,8,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(9,4,4,12,4,'烧鹅皮很脆，米饭香。',NULL,1,2,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(10,1,5,13,4,'剁椒鱼头够辣，配米饭能吃三碗。',NULL,1,4,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(11,3,6,15,5,'刺身很新鲜，厚切很满足。',NULL,1,11,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(12,2,6,16,5,'鸡皮串必点，配清酒完美。',NULL,1,7,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(13,3,7,17,4,'五花肉很香，小菜可以无限续。',NULL,1,3,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(14,4,8,18,4,'面很筋道，汤头清爽。',NULL,1,5,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(15,1,8,19,5,'肉夹馍肥瘦相间，性价比高。',NULL,1,6,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(16,5,1,1,1,'这条是违规测试评论（含广告内容），等待管理员删除。',NULL,0,0,'2026-10-24 13:14:06','2026-10-24 13:14:06'),(2001,1,101,1001,4,'环境干净，上菜很快，招牌菜确实名不虚传。',NULL,1,2,'2026-10-23 14:35:37','2026-10-23 14:35:37'),(2002,2,101,1002,5,'和朋友聚餐来的，人均不贵，味道稳定，还会再来。',NULL,1,1,'2026-10-23 14:35:37','2026-10-23 14:35:37'),(2003,2,102,1004,5,'味道不错，就是饭点需要排队，建议提前取号。',NULL,1,5,'2026-10-22 14:35:37','2026-10-22 14:35:37'),(2004,3,102,1005,4,'服务很热情，菜品分量足，适合家庭聚餐。',NULL,1,6,'2026-10-22 14:35:37','2026-10-22 14:35:37'),(2005,3,103,1007,4,'第一次来，点了三个菜都没踩雷，性价比很高。',NULL,1,8,'2026-10-21 14:35:37','2026-10-21 14:35:37'),(2006,4,103,1008,5,'口味偏重，喜欢清淡的记得备注少油少盐。',NULL,1,9,'2026-10-21 14:35:37','2026-10-21 14:35:37'),(2007,4,104,1010,5,'店面不大但很温馨，甜品是惊喜。',NULL,1,11,'2026-10