DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `phone` varchar(20) NOT NULL COMMENT '手机号（登录账号）',
  `password` varchar(100) NOT NULL COMMENT 'BCrypt 密码',
  `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像地址',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `taste_cuisine` varchar(100) DEFAULT NULL COMMENT '偏好菜系，逗号分隔',
  `taste_flavor` varchar(20) DEFAULT NULL COMMENT '口味轻重：清淡/微辣/中辣/重辣',
  `taboo` varchar(200) DEFAULT NULL COMMENT '忌口食材，逗号分隔',
  `status` tinyint DEFAULT '1' COMMENT '1 正常 0 禁用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint DEFAULT '0' COMMENT '逻辑删除 0 未删除 1 已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=8001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='普通用户表';
